insert into public.listings (seller_id, title, slug, summary, description, category, price_cents, material, process, phone_models, images, params) values
(null, 'Capa DÍGITO', 'capa-digito-tpu', 'Capa em TPU 95A com quatro encaixes posicionados para a tua mão.', 'A base de tudo. Parede de 2,4 mm que engrossa nos cantos até 5,5 mm, placa traseira com alvéolos hexagonais e quatro encaixes hexagonais com sede para íman. Os encaixes são colocados a partir das tuas medidas: depois da compra recebes um link para medir a mão com uma foto, ou usamos a estimativa pela tua altura.', 'capa', 2400, 'TPU 95A', 'FDM', array['IPHONE_16_PRO_MAX','IPHONE_16_PRO','GALAXY_S23_ULTRA','PIXEL_9_PRO_XL','PIXEL_9_PRO'], array['/products/capa.webp'], '{"type":"case"}'),
(null, 'Kit Sela ×4', 'kit-sela-petg-cf', 'Quatro pegas em sela, uma por dedo, com o raio de cada berço calculado para esse dedo.', 'Cada sela tem um berço côncavo de raio R = w / (2·sin 72°), onde w é a largura do teu dedo na articulação do meio. Impressas em PETG-CF mate, com macho hexagonal de 9,6 mm e sede para íman Ø6×2.', 'kit', 1800, 'PETG-CF', 'FDM', array['IPHONE_16_PRO_MAX','IPHONE_16_PRO','GALAXY_S23_ULTRA','PIXEL_9_PRO_XL','PIXEL_9_PRO'], array['/products/sela.webp'], '{"type":"sela","count":4}'),
(null, 'Anel à medida', 'anel-pa12', 'Um anel com diâmetro interior igual à largura do dedo mais 1,2 mm.', 'Para quem segura o telemóvel com um dedo enfiado. Banda de 3 mm em PA12 sinterizado, sem suportes nem marcas de camada visíveis. Encaixa em qualquer um dos quatro encaixes da capa.', 'pega', 1200, 'PA12', 'SLS', array['IPHONE_16_PRO_MAX','IPHONE_16_PRO','GALAXY_S23_ULTRA','PIXEL_9_PRO_XL','PIXEL_9_PRO'], array['/products/anel.webp'], '{"type":"ring"}'),
(null, 'Tampas cegas ×4', 'tampas-cegas', 'Fecham os encaixes quando queres a capa lisa para o bolso.', 'Tampas hexagonais que ficam rentes à capa. Tiras as pegas, pões as tampas, e a capa volta a deslizar no bolso. Em PETG-CF, com íman.', 'acessorio', 600, 'PETG-CF', 'FDM', array['IPHONE_16_PRO_MAX','IPHONE_16_PRO','GALAXY_S23_ULTRA','PIXEL_9_PRO_XL','PIXEL_9_PRO'], array['/products/tampa.webp'], '{"type":"blank","count":4}'),
(null, 'Ímanes N42 Ø6×2 ×8', 'imanes-n42', 'Ímanes de neodímio para substituir ou para imprimires as tuas pegas.', 'Oito ímanes Ø6×2 mm, grau N42, com revestimento de níquel. Medida exata das sedes das pegas e da capa DÍGITO.', 'acessorio', 400, 'NdFeB N42', null, array[]::text[], array['/products/imanes.webp'], '{"type":"magnet","count":8}'),
(null, 'Sela em titânio', 'sela-titanio', 'Uma pega em Ti6Al4V, fundida a laser camada a camada e polida à mão.', 'A mesma geometria da sela, impressa por fusão seletiva a laser em titânio de grau 5. Mais fina, mais fria ao toque e praticamente eterna. Encaixe hexagonal com folga de 0,10 mm.', 'pega', 6900, 'Ti6Al4V', 'SLM', array['IPHONE_16_PRO_MAX','IPHONE_16_PRO','GALAXY_S23_ULTRA','PIXEL_9_PRO_XL','PIXEL_9_PRO'], array['/products/titanio.webp'], '{"type":"sela","metal":true}');
